from common import *

low=r'''
struct LowLink {
    int n,idx,cnt;vector<vector<pair<int,int>>>e;vector<pair<int,int>>edges;
    vector<int>dfn,low,sz,cut,bridge,bel;vector<vector<int>>parts,bcc;
    void init(int n_){n=n_;idx=cnt=0;e.assign(n+1,{});edges.clear();dfn.assign(n+1,0);low=dfn;sz=dfn;cut=dfn;bel=dfn;parts.assign(n+1,{});bridge.clear();bcc.clear();}
    void addedge(int u,int v){int id=edges.size();edges.push_back({u,v});bridge.push_back(0);e[u].push_back({v,id});e[v].push_back({u,id});}
    void dfs(int u,int id){dfn[u]=low[u]=++idx;sz[u]=1;int ch=0;for(auto[v,id2]:e[u]){if(id2==id)continue;if(!dfn[v]){ch++;dfs(v,id2);sz[u]+=sz[v];low[u]=min(low[u],low[v]);if(low[v]>dfn[u])bridge[id2]=1;if(low[v]>=dfn[u]){parts[u].push_back(sz[v]);if(id!=-1)cut[u]=1;}}else low[u]=min(low[u],dfn[v]);}if(id==-1&&ch>=2)cut[u]=1;}
    void paint(int u){bel[u]=cnt;bcc.back().push_back(u);for(auto[v,id]:e[u])if(!bridge[id]&&!bel[v])paint(v);}
    void run(){for(int u=1;u<=n;u++)if(!dfn[u])dfs(u,-1);for(int u=1;u<=n;u++)if(!bel[u]){cnt++;bcc.push_back({});paint(u);}}
};
'''
add('图论','割边','LowLink',low,'无向图桥检测，按唯一边号跳过父边；支持重边和自环。','O(n+m)时间与空间。',[('addedge(u,v)','自动分配0-based边号'),('run()','dfs森林；bridge[id]标记桥'),('edges/e','原边端点与邻接表')],['跳过父边号而非父节点，否则重边会误判。','bridge判low[v]>dfn[u]，严格大于。','深链递归有栈风险。'],['图/图论竞赛复习_严格课件注释版.md'],[
example('P1656','炸铁路','https://www.luogu.com.cn/problem/P1656','输出删除后使图不连通的铁路。','这正是桥的定义。','run后筛bridge，端点排序后按字典序输出。','O(n+m+k log k)时间、O(n+m)空间。',r'''void solve(){int n,m;cin>>n>>m;LowLink g;g.init(n);while(m--){int u,v;cin>>u>>v;g.addedge(u,v);}g.run();vector<pair<int,int>>ans;for(int i=0;i<(int)g.edges.size();i++)if(g.bridge[i]){auto[u,v]=g.edges[i];if(u>v)swap(u,v);ans.push_back({u,v});}sort(ans.begin(),ans.end());for(auto[u,v]:ans)cout<<u<<' '<<v<<'\n';}'''),
example('CF118E','Bertown Roads','https://codeforces.com/problemset/problem/118/E','把连通无向图定向为强连通图。','存在桥时不可能；无桥时DFS树边向下、返祖边向上可得强连通方向。','先run判桥；沿dfn更早到更晚识别树边，另一次DFS每边只定向一次。','O(n+m)时间与空间。',r'''void solve(){int n,m;cin>>n>>m;LowLink g;g.init(n);while(m--){int u,v;cin>>u>>v;g.addedge(u,v);}g.run();for(int b:g.bridge)if(b){cout<<0<<'\n';return;}vector<int>vis(n+1),used(g.edges.size());vector<pair<int,int>>ans(g.edges.size());function<void(int)>dfs=[&](int u){vis[u]=1;for(auto[v,id]:g.e[u])if(!used[id]){used[id]=1;ans[id]={u,v};if(!vis[v])dfs(v);}};dfs(1);for(auto[u,v]:ans)cout<<u<<' '<<v<<'\n';}''')])

add('图论','割点','LowLink',low,'无向图割点与删点分块大小统计；根与非根分开判定。','O(n+m)时间与空间。',[('cut[u]','割点标记'),('parts[u]','low[v]>=dfn[u]的子树大小'),('sz[u]','DFS子树大小')],['根需至少两个DFS儿子；非根条件为low[v]>=dfn[u]。','BLO删除边后仍保留被隔离顶点，必须计入涉及该点的有序点对。'],['图/图论竞赛复习_严格课件注释版.md'],[
example('P3388','割点','https://www.luogu.com.cn/problem/P3388','输出全部割点。','Tarjan low判定去点后有子树无法连回祖先。','run遍历非连通图；按cut扫描。','O(n+m)时间与空间。',r'''void solve(){int n,m;cin>>n>>m;LowLink g;g.init(n);while(m--){int u,v;cin>>u>>v;g.addedge(u,v);}g.run();vector<int>ans;for(int u=1;u<=n;u++)if(g.cut[u])ans.push_back(u);cout<<ans.size()<<'\n';for(int u:ans)cout<<u<<' ';cout<<'\n';}'''),
example('P3469','BLO-Blockade','https://www.luogu.com.cn/problem/P3469','分别封锁每个点的所有边，统计不连通有序点对。','原图连通，删边后分块；总点对减去各块内部点对。','利用parts[u]与剩余块n-1-sum(parts)，再加2(n-1)。','O(n+m)时间与空间。',r'''void solve(){int n,m;cin>>n>>m;LowLink g;g.init(n);while(m--){int u,v;cin>>u>>v;g.addedge(u,v);}g.run();for(int u=1;u<=n;u++){int rest=n-1,ans=2*(n-1)+(n-1)*(n-1);for(int s:g.parts[u]){rest-=s;ans-=s*s;}ans-=rest*rest;cout<<ans<<'\n';}}''')])

add('图论','边双连通分量','LowLink',low,'去掉所有桥后得到边双分量，缩点得到桥森林。','O(n+m)时间与空间。',[('run()','先判桥再paint非桥边'),('bel[u]','边双编号1..cnt'),('bcc','分量成员表')],['桥树不是原图生成树，分量内可能有很多环。','Redundant Paths保证连通；不连通情况不能直接套叶子公式。'],['图/图论竞赛复习_严格课件注释版.md'],[
example('P8436','边双连通分量','https://www.luogu.com.cn/problem/P8436','输出边双数量及每个分量的点。','桥分隔分量，删除桥后的连通块就是答案。','run后输出bcc。','O(n+m)时间与空间。',r'''void solve(){int n,m;cin>>n>>m;LowLink g;g.init(n);while(m--){int u,v;cin>>u>>v;g.addedge(u,v);}g.run();cout<<g.bcc.size()<<'\n';for(auto&c:g.bcc){cout<<c.size();for(int u:c)cout<<' '<<u;cout<<'\n';}}'''),
example('P2860','Redundant Paths','https://www.luogu.com.cn/problem/P2860','最少加边让任意两点有两条边不重叠路径。','缩为桥树后，配对叶子可消除所有桥；答案ceil(叶子数/2)。','用原边与bel计算桥树度数，数度1点。','O(n+m)时间与空间。',r'''void solve(){int n,m;cin>>n>>m;LowLink g;g.init(n);while(m--){int u,v;cin>>u>>v;g.addedge(u,v);}g.run();vector<int>d(g.cnt+1);for(auto[u,v]:g.edges)if(g.bel[u]!=g.bel[v]){d[g.bel[u]]++;d[g.bel[v]]++;}int leaf=0;for(int i=1;i<=g.cnt;i++)leaf+=d[i]==1;cout<<(leaf+1)/2<<'\n';}''')])

vdcc=source_struct('图/图论竞赛复习_按课件整理.md','VDCC')
add('图论','点双连通分量','VDCC',vdcc,'Tarjan点栈构造点双；割点可属于多个块，孤立点单独成块。','O(n+m)时间与空间。',[('init(n)','清空状态'),('addedge(u,v,id)','无向边唯一编号，忽略自环'),('run()','得到bcc与cut')],['low[v]>=dfn[u]时弹到v，再把u加入块。','不能把点双编号当作每点唯一归属。'],['图/图论竞赛复习_按课件整理.md'],[
example('P8435','点双连通分量','https://www.luogu.com.cn/problem/P8435','输出所有点双。','直接调用点栈Tarjan。','边号0..m-1；run后输出bcc。','O(n+m)时间与空间。',r'''void solve(){int n,m;cin>>n>>m;VDCC g;g.init(n);for(int id=0;id<m;id++){int u,v;cin>>u>>v;g.addedge(u,v,id);}g.run();cout<<g.bcc.size()<<'\n';for(auto&c:g.bcc){cout<<c.size();for(int u:c)cout<<' '<<u;cout<<'\n';}}'''),
example('P3225','矿场搭建','https://www.luogu.com.cn/problem/P3225','设置最少出口，保证任一矿点坍塌后仍可逃离，统计方案数。','块无割点需2出口；叶子块有1割点需在非割点中选1出口。','按边中出现的编号建图，run后逐bcc统计cut数并乘方案。','O(n+m)时间与空间，方案数按题目保证使用unsigned long long。',r'''void solve(){int m,tc=0;while(cin>>m&&m){vector<pair<int,int>>e(m);int n=0;for(auto&[u,v]:e){cin>>u>>v;n=max(n,max(u,v));}VDCC g;g.init(n);vector<int>present(n+1);for(int i=0;i<m;i++){auto[u,v]=e[i];present[u]=present[v]=1;g.addedge(u,v,i);}g.run();int need=0;unsigned long long ways=1;for(auto&c:g.bcc){if(!present[c[0]])continue;int cuts=0;for(int u:c)cuts+=g.cut[u];int s=c.size();if(cuts==0){need+=2;ways*=1ULL*s*(s-1)/2;}else if(cuts==1){need++;ways*=s-1;}}cout<<"Case "<<++tc<<": "<<need<<' '<<ways<<'\n';}}''')])

sat=source_struct('图/图论竞赛复习_严格课件注释版.md','SCC')+'\n'+source_struct('图/图论竞赛复习_严格课件注释版.md','TwoSAT')
add('图论','2-SAT','TwoSAT',sat,'二元布尔变量OR子句与蕴含约束；内部独立Tarjan SCC。','O(变量数+子句数)时间与空间。',[('init_sat(n)','n个变量，1-based'),('add_or(a,A,b,B)','(a=A)或(b=B)'),('imply(u,v)','自动添加逆否边'),('solve_sat()','可行后ans保存0/1解')],['取值公式依赖Tarjan的反拓扑分量编号，不能直接替换为Kosaraju。','每次判定需重新初始化图；矛盾时ans无效。'],['图/图论竞赛复习_严格课件注释版.md'],[
example('P4782','2-SAT','https://www.luogu.com.cn/problem/P4782','给OR子句求一个可行布尔赋值。','每条OR拆成两个蕴含，变量两取值不能在同一SCC。','add_or建图，solve_sat后输出ans。','O(n+m)时间与空间。',r'''void solve(){int n,m;cin>>n>>m;TwoSAT sat;sat.init_sat(n);while(m--){int a,A,b,B;cin>>a>>A>>b>>B;sat.add_or(a,A,b,B);}if(!sat.solve_sat()){cout<<"IMPOSSIBLE\n";return;}cout<<"POSSIBLE\n";for(int i=1;i<=n;i++)cout<<sat.ans[i]<<(i==n?'\n':' ');}'''),
example('P4171','满汉全席','https://www.luogu.com.cn/problem/P4171','每种材料做满式或汉式，满足每位评委至少喜欢一种菜。','评委条件是两个取值命题的OR子句。','h映射1、m映射0；每组init后add_or并判定。','O(总变量+总条件)时间与空间。',r'''void solve(){int T;cin>>T;while(T--){int n,m;cin>>n>>m;TwoSAT sat;sat.init_sat(n);while(m--){char a,b;int x,y;cin>>a>>x>>b>>y;sat.add_or(x,a=='h',y,b=='h');}cout<<(sat.solve_sat()?"GOOD":"BAD")<<'\n';}}''')])
